import{_ as n,o as r,c as a,ag as t}from"./chunks/framework.B-XtCDNB.js";const m=JSON.parse('{"title":"Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"release_notes.md","filePath":"release_notes.md"}'),i={name:"release_notes.md"};function u(s,e,d,l,o,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><h2 id="isi-2-0-juli-2026-version-2-0-0" tabindex="-1">ISI 2.0 Juli 2026 Version 2.0.0 <a class="header-anchor" href="#isi-2-0-juli-2026-version-2-0-0" aria-label="Permalink to &quot;ISI 2.0 Juli 2026 Version 2.0.0&quot;">​</a></h2><h3 id="infrastrukturabfragen" tabindex="-1">Infrastrukturabfragen <a class="header-anchor" href="#infrastrukturabfragen" aria-label="Permalink to &quot;Infrastrukturabfragen&quot;">​</a></h3><p>Die Begriffe im <strong>Bauleitplanverfahren</strong> sind standardisiert und gewährleisten die Kompatibilität mit dem Objektartenkatalog des Standards Xplanung. In der Abfrage wurde das Feld &quot;Stand des Verfahrens“ umbenannt in &quot;Verfahrensstand&quot;. Außerdem wurde in der Abfragevariante der Begriff „Wesentliche Rechtsgrundlage“ in „Planart“ geändert. Die bisherigen zur Verfügung stehenden Optionen im Dropdownfeld wurden in beiden Feldern angepasst.</p><p>Die Dropdown-Menüs im Verfahren <strong>Baugenehmigungsverfahren</strong> wurden in Anlehnung an ProLBK zur Verbesserung der Kommunikation mit der HA IV bzw. der Begutachtung der HAII angepasst. In der Abfrage wurde das Feld „Stand des Verfahrens“ umbenannt in &quot;Verfahrensstand&quot; und die Optionen im Dropdownfeld an die Gegebenheiten des Baugenehmigungsverfahren angepasst. In der Abfragevariante wurden die Optionen des Dropdownfeldes &quot;Wesentliche Rechtsgrundlage&quot; abgestimmt. Zur besseren Übersicht wurde das Menü zum Fördermix an die Gegebenheiten der Abfrageart Baugenehmigungsverfahren angepasst.</p><p>Die entsprechenden Begriffe der Abfrageart <strong>Weiteres Verfahren</strong> wurden entsprechen der Änderungen der Begrifflichkeiten im Bauleitplan- bzw. Baugenehmigungsverfahren angepasst.</p><p>Alle Abfragearten haben ein neues Symbol erhalten, dieses wird in allen Formularen und in erstellten Objekten angezeigt, um während der Bearbeitung immer zu erkennen, um welche Abfrageart es sich handelt. Außerdem ist es für die Nutzenden möglich, über das neue Icon zu &quot;hovern&quot;, um die Abfrageart angezeigt zu bekommen. In der Abfragevariante aller Abfragearten wurden zur Vermeidung von Missverständnissen Informationen zu den Sonderwohnformen verändert.</p><h3 id="vorhaben-ehemals-bauvorhaben" tabindex="-1">Vorhaben (ehemals Bauvorhaben) <a class="header-anchor" href="#vorhaben-ehemals-bauvorhaben" aria-label="Permalink to &quot;Vorhaben (ehemals Bauvorhaben)&quot;">​</a></h3><p>Für ein gemeinsames Verständnis wurde der Begriff Bauvorhaben in Vorhaben verändert. Im Vorhaben erfolgte ein Abgleich der Begrifflichkeiten zu allen Abfragearten. Sobald ein neuer Kommentar im Vorhaben verfasst wird, wird eine E-Mail mit Informationen zu Name und Link des Vorhabens, alle verknüpften Abfragen sowie Text und Datum des Kommentars an eine Gruppen E-Mail für die Sachbearbeitung gesandt. Das Datumsfeld ist standardmäßig mit dem Erstellungsdatum versehen, kann jedoch weiterhin verändert werden</p><h3 id="verortung" tabindex="-1">Verortung <a class="header-anchor" href="#verortung" aria-label="Permalink to &quot;Verortung&quot;">​</a></h3><p>In der Karte zur Verortung können nun neben den Flurstücken auch die Umgriffe der Baublöcke und Bebauungspläne für eine Verortung zur Auswahl herangezogen werden. Es wurde der Förderschulsprengel in der Karte als Geodatenlayer integriert.</p><h3 id="benutzerfreundlichkeit" tabindex="-1">Benutzerfreundlichkeit <a class="header-anchor" href="#benutzerfreundlichkeit" aria-label="Permalink to &quot;Benutzerfreundlichkeit&quot;">​</a></h3><p>Die Informations-E-Mails zum Vorliegen eines Arbeitsauftrags für alle Rollen wurden um einen Link, der direkt zur entsprechenden Abfrage führt, ergänzt. Neben dem Link erhält man zusätzlich Informationen zur Bearbeitungsfrist. Das Feld Fördermix wurde als Pflichtfeld entsprechend gekennzeichnet. Für die Sachbearbeitung ist es möglich, aus einer Abfrage mit einem Klick in ein verknüpftes Vorhaben springen, um die Kommentare im Vorhaben schnell lesen zu können. Das Vorhaben wird dabei in einem neuen Fenster geöffnet. Bei nachträglicher Veränderung des Attributes &quot;Realisierung von&quot; können die Bauraten in Anlehnung an die Veränderung neu ermittelt werden.</p><h3 id="stammdaten" tabindex="-1">Stammdaten <a class="header-anchor" href="#stammdaten" aria-label="Permalink to &quot;Stammdaten&quot;">​</a></h3><p>Die Bevölkerungs- und Prognosedaten wurden entsprechend der neuen Vorgaben angepasst. Das hinterlegte Schema zur Berechnung der idealtypischen Bauraten in den Stammdaten wird gemäß der den neuen Vorgaben aktualisiert und für die Berechnungen genutzt. Im Vergleich zu den bisher hinterlegten idealtypischen Bauraten wird der idealtypische Realisierungszeitraum in jeder Bauvorhabengröße um bis zu 2 Jahre verlängert und umfasst nun bis zu 9 Jahre. Bei der SoBoN-Berechnung erfolgte eine Aktualisierung bei der Aufteilung der Wohneinheiten auf Bauraten.</p><p>Die Stammdaten zu den städtebaulichen SoBoN-Orientierungswerten (Geschossfläche und Einwohneranzahl) sind an die neuen Stadtratsvorgaben angepasst. Dabei wurde ein neues Feld &quot;Start 4.2-Verfahren&quot; im Formular der Abfrageart Bauleitplanverfahren im Kasten &quot;Allgemeine Informationen zum Verfahren&quot; implementiert und ein weiteres Feld &quot;Datum unbekannt&quot; steht als Tickbox zur Verfügung, wobei diese beiden Felder bilden in Kombination (entweder oder) Pflichtfelder. Eine neues Dropdown-Menü &quot;Bauratenmethodik&quot; ist im Formular der Abfrageart Bauleitplanverfahren implementiert.</p><h3 id="technische-anpassungen" tabindex="-1">Technische Anpassungen <a class="header-anchor" href="#technische-anpassungen" aria-label="Permalink to &quot;Technische Anpassungen&quot;">​</a></h3><p>Ein dedizierter Entwicklungsbranch wurde eingerichtet werden, um die zukünftige Entwicklung sauber vom aktuellen Stand zu trennen und eine strukturierte Weiterentwicklung zu ermöglichen. Außerdem wurden zwei neue Datenbank Instanzen auf Test für die Test- und die Demoumgebung erstellt, auf die ein Zugriff möglich ist.</p><p>Zur besseren Verwaltung der Reporte sind diese in einem einfachen lesbaren SQL-Abfrage migriert. Dabei werden auch mehrfach genutzte Logiken in spezielle Fragen ausgelagert (Modularisierung).</p>',19)])])}const f=n(i,[["render",u]]);export{m as __pageData,f as default};
